   479  static void _parse_error(struct vcardparser_state *state,
   480                           enum vcardparameter_xlicerrortype type,
   481                           const char *fmt, ...)
   482  {
   483      va_list ap;
   484
   485      va_start(ap, fmt);
   486      buf_reset(&state->errbuf);
   487      buf_vprintf(&state->errbuf, fmt, ap);
   488      va_end(ap);
   489
   490      if (state->prop) {
   491          vcardproperty_free(state->prop);
   492      }
   493
   494      /* coverity[resource_leak] */
   495      vcardparameter *errParam = vcardparameter_new_xlicerrortype(type);
   496      state->prop = vcardproperty_vanew_xlicerror(buf_cstring(&state->errbuf),
   497                                                  errParam,
   498                                                  (void *)0);
   499      buf_reset(&state->buf);
   500  }
